To implement a custom transformer for your regression model, you can modify your existing code slightly. Here’s an example of how to properly inherit from both `BaseEstimator` and `TransformerMixin` to ensure compatibility with scikit-learn:

```python
import numpy as np
import sklearn
from sklearn.compose import TransformedTargetRegressor
from sklearn.linear_model import LinearRegression

class MyTransform(sklearn.base.BaseEstimator, sklearn.base.TransformerMixin):
    def fit(self, *_, **__):
        return self

    def transform(self, X):
        return np.array(X) * 10

    def inverse_transform(self, X):
        return np.array(X) / 10

def MyLinearRegression():
    return TransformedTargetRegressor(
        regressor=LinearRegression(),
        transformer=MyTransform()
    )

def test():
    model = MyLinearRegression()
    model.fit(X=[[1], [2], [3]], y=[10, 20, 30])
    predictions = model.predict(X=[[4], [5]])
    print(predictions)
```

